<script setup lang="ts">
import { ref, computed, onMounted, watch } from 'vue'
import { 
  RefreshCw, 
  AlertCircle, 
  Download,
  DollarSign,
  Repeat,
  Calendar,
  BarChart3,
  Target,
  CheckCircle,
  AlertTriangle,
  Info,
  TrendingUp
} from 'lucide-vue-next'
import { call } from 'frappe-ui'
import { cacheService, CACHE_KEYS } from '../../services/cache-service.js'
import { session } from '../../data/session.js'

const CACHE_EXPIRY = 5 * 60 * 1000 // 5 minutes

// State
const loading = ref(false)
const error = ref('')
const selectedReport = ref('summary')
const selectedPeriod = ref('last_3_months')
const reportData = ref({
  total_income: 0,
  recurring_income: 0,
  one_time_income: 0,
  income_by_type: {},
  monthly_trends: []
})
const insights = ref([])
const recommendations = ref([])
const scores = ref({
  stability: 0,
  diversification: 0,
  growth: 0
})

// Cache key generator
const getCacheKey = (reportType: string, period: string) => {
  return `${CACHE_KEYS.INCOME_ANALYTICS}_${reportType}_${period}`
}

const getInsightsCacheKey = () => {
  return CACHE_KEYS.INCOME_INSIGHTS
}

// Methods
const loadReportData = async (forceRefresh = false) => {
  try {
    const cacheKey = getCacheKey(selectedReport.value, selectedPeriod.value)
    
    // Check cache first unless force refresh
    if (!forceRefresh) {
      const cachedData = cacheService.get(cacheKey, {
        userId: session.user,
        maxAge: CACHE_EXPIRY
      })
      
      if (cachedData) {
        reportData.value = cachedData.reportData
        if (cachedData.insights) {
          insights.value = cachedData.insights
          recommendations.value = cachedData.recommendations
          scores.value = cachedData.scores
        }
        return
      }
    }

    loading.value = true
    error.value = ''

    // Load analytics data
    const analytics = await call('artha.api.income.get_income_analytics', {
      period: selectedPeriod.value
    })

    reportData.value = analytics

    // Prepare cache data
    const cacheData = {
      reportData: analytics,
      insights: null,
      recommendations: null,
      scores: null
    }

    // Load insights if detailed report is selected
    if (selectedReport.value === 'detailed') {
      // Check insights cache first
      const insightsCacheKey = getInsightsCacheKey()
      let insightsData: any = null
      
      if (!forceRefresh) {
        insightsData = cacheService.get(insightsCacheKey, {
          userId: session.user,
          maxAge: CACHE_EXPIRY
        })
      }
      
      if (!insightsData) {
        insightsData = await call('artha.api.income.get_income_insights')
        // Cache insights separately as they don't change with period
        cacheService.set(insightsCacheKey, insightsData, {
          userId: session.user,
          maxAge: CACHE_EXPIRY
        })
      }
      
      if (insightsData) {
        insights.value = insightsData.insights || []
        recommendations.value = insightsData.recommendations || []
        scores.value = insightsData.scores || { stability: 0, diversification: 0, growth: 0 }
        
        // Update cache data with insights
        cacheData.insights = insightsData.insights
        cacheData.recommendations = insightsData.recommendations
        cacheData.scores = insightsData.scores
      }
    }

    // Cache the data using centralized cache service
    cacheService.set(cacheKey, cacheData, {
      userId: session.user,
      maxAge: CACHE_EXPIRY
    })

  } catch (err) {
    console.error('Failed to load report data:', err)
    error.value = err.message || 'Failed to load report data'
  } finally {
    loading.value = false
  }
}

const refreshReports = () => {
  // Force refresh by clearing cache for current selection
  const cacheKey = getCacheKey(selectedReport.value, selectedPeriod.value)
  cacheService.delete(cacheKey, { userId: session.user })
  
  // Also clear insights cache if detailed report
  if (selectedReport.value === 'detailed') {
    const insightsCacheKey = getInsightsCacheKey()
    cacheService.delete(insightsCacheKey, { userId: session.user })
  }
  
  loadReportData(true)
}

const clearAllCache = () => {
  // Clear all income analytics related cache
  cacheService.clearPattern('income-analytics')
  cacheService.clearPattern('income-insights')
}

const exportReport = () => {
  // Generate CSV data
  const csvData = generateCSVData()
  
  // Create and download file
  const blob = new Blob([csvData], { type: 'text/csv' })
  const url = window.URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = `income-report-${selectedReport.value}-${selectedPeriod.value}-${new Date().toISOString().split('T')[0]}.csv`
  document.body.appendChild(link)
  link.click()
  document.body.removeChild(link)
  window.URL.revokeObjectURL(url)
}

const generateCSVData = () => {
  let csv = ''
  
  if (selectedReport.value === 'summary') {
    csv = 'Income Type,Amount,Percentage\n'
    Object.entries(reportData.value.income_by_type).forEach(([type, amount]) => {
      const numAmount = Number(amount)
      const percentage = ((numAmount / reportData.value.total_income) * 100).toFixed(1)
      csv += `"${type}",${numAmount},${percentage}%\n`
    })
  } else if (selectedReport.value === 'trends') {
    csv = 'Month,Total,Recurring,One-time\n'
    reportData.value.monthly_trends.forEach((trend: any) => {
      csv += `"${trend.month}",${trend.total},${trend.recurring},${trend.one_time}\n`
    })
  }
  
  return csv
}

const formatPeriod = (period: string) => {
  const map = {
    'this_month': 'This Month',
    'last_month': 'Last Month',
    'last_3_months': 'Last 3 Months',
    'last_6_months': 'Last 6 Months',
    'this_year': 'This Year'
  }
  return map[period] || period
}

const getTypeColor = (type: string) => {
  const colors = [
    '#3B82F6', '#10B981', '#F59E0B', '#EF4444', '#8B5CF6',
    '#06B6D4', '#84CC16', '#F97316', '#EC4899', '#6366F1'
  ]
  const index = type.length % colors.length
  return colors[index]
}

// Watch for changes in report type or period
watch([selectedReport, selectedPeriod], () => {
  loadReportData()
})

// Lifecycle
onMounted(async () => {
  try {
    // Only load data if not already cached - this prevents unnecessary API calls
    // when switching between Management and Reports sections
    await loadReportData()
  } catch (error) {
    console.error('Reports: Failed to initialize:', error)
  }
})
</script>

